    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Patient #60905: A 7-year-old child presents with a limp that started yesterday morning. Two weeks ago, he had a mild URI. He is well-appearing. He refuses to bear weight fully but has only mild pain with passive hip ROM. Labs show a normal WBC count and an ESR of 15 mm/hr. What is the most likely diagnosis?', '["Slipped capital femoral epiphysis", "Septic arthritis", "Legg-Calv\u00e9-Perthes disease", "Juvenile idiopathic arthritis", "Transient synovitis"]'::jsonb, 4, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'Patient #87343: An 11-year-old overweight adolescent undergoes in situ pinning for a stable Slipped Capital Femoral Epiphysis (SCFE). At follow-up, the patient complains of severe stiffness and loss of joint space is noted on X-ray. What is this devastating complication?', '["Infection", "Nonunion", "Heterotopic ossification", "Avascular necrosis of the femoral head", "Chondrolysis"]'::jsonb, 4, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'Patient #98845: An 12-year-old overweight adolescent undergoes in situ pinning for a stable Slipped Capital Femoral Epiphysis (SCFE). At follow-up, the patient complains of severe stiffness and loss of joint space is noted on X-ray. What is this devastating complication?', '["Infection", "Avascular necrosis of the femoral head", "Chondrolysis", "Nonunion", "Heterotopic ossification"]'::jsonb, 2, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 12-year-old soccer player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Intra-articular corticosteroid injection", "Strict non-weight bearing with crutches", "Immobilization in a long leg cast for 6 weeks", "Surgical excision of the ossicle", "Activity modification, ice, NSAIDs, and reassurance"]'::jsonb, 4, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'A 1-month-old female infant is diagnosed with Developmental Dysplasia of the Hip (DDH) via ultrasound. The hip is reducible. What is the standard first-line treatment for this patient?', '["Triple diapering", "Pavlik harness", "Closed reduction and spica casting", "Observation only", "Open reduction and pelvic osteotomy"]'::jsonb, 1, 'For infants < 6 months of age with a reducible dysplastic or dislocated hip, the Pavlik harness is the gold standard treatment. It maintains the hip in flexion and abduction, promoting concentric reduction and acetabular remodeling. Closed reduction is typically reserved for failures or children 6-18 months.'),
    (v_topic_id, 'A 13-year-old female football lineman complains of insidious onset, mechanical low back pain that is exacerbated by extension activities (e.g., back walkovers). Neurologic exam is normal. Oblique radiographs of the lumbar spine demonstrate a ''collar'' on the ''Scotty dog''. What is the specific anatomic defect in this condition?', '["Herniation of the nucleus pulposus", "Fracture of the transverse process", "Defect in the vertebral body endplate (Schmorl node)", "Congenital failure of segmentation of the lumbar vertebrae", "Defect in the pars interarticularis"]'::jsonb, 4, 'Spondylolysis is a stress fracture or defect of the pars interarticularis. It is highly prevalent in adolescent athletes participating in sports involving repetitive lumbar hyperextension. On oblique radiographs, a radiolucent gap in the pars resembles a collar on the neck of the ''''Scotty dog''''.'),
    (v_topic_id, 'A 2-month-old male infant is diagnosed with Developmental Dysplasia of the Hip (DDH) via ultrasound. The hip is reducible. What is the standard first-line treatment for this patient?', '["Observation only", "Pavlik harness", "Triple diapering", "Closed reduction and spica casting", "Open reduction and pelvic osteotomy"]'::jsonb, 1, 'For infants < 6 months of age with a reducible dysplastic or dislocated hip, the Pavlik harness is the gold standard treatment. It maintains the hip in flexion and abduction, promoting concentric reduction and acetabular remodeling. Closed reduction is typically reserved for failures or children 6-18 months.'),
    (v_topic_id, 'A 20-day-old infant is brought to the clinic for bilateral clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Varus", "Adductus", "Cavus", "Equinus", "Supination"]'::jsonb, 3, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 4-year-old child refuses to bear weight on the right leg. The hip is held in flexion, abduction, and external rotation. Temperature is 40.0°C. Laboratory evaluation shows a WBC count of 15,000/mm³ and an ESR of 50 mm/hr. According to the Kocher criteria, what is the probability that this child has septic arthritis rather than transient synovitis?', '["> 90% (Very high probability)", "About 25%", "< 10% (Very low probability)", "About 50%", "Exactly 0%"]'::jsonb, 0, 'The Kocher criteria differentiate septic arthritis from transient synovitis. The 4 criteria are: non-weight-bearing, fever > 38.5°C, ESR > 40 mm/hr, and WBC > 12,000/mm³. Having all 4 predictors yields a 99% probability of septic arthritis; 3 predictors yield a 93% probability. This child has 4 predictors.'),
    (v_topic_id, 'A 1-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the left. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["CT scan of the pelvis", "MRI of the hips", "Ultrasound of the hips", "AP radiograph of the pelvis", "Bone scan"]'::jsonb, 2, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 6-year-old falls from monkey bars and sustains a significantly displaced extension-type supracondylar humerus fracture. Upon examination, the child is unable to make an ''OK'' sign (unable to flex the IP joint of the thumb and DIP joint of the index finger). Which nerve is most likely injured?', '["Axillary nerve", "Musculocutaneous nerve", "Anterior interosseous nerve (AIN)", "Radial nerve", "Ulnar nerve"]'::jsonb, 2, 'The anterior interosseous nerve (AIN), a branch of the median nerve, is the most commonly injured nerve in extension-type supracondylar humerus fractures. Injury manifests as an inability to flex the IP joint of the thumb (flexor pollicis longus) and the DIP of the index finger (flexor digitorum profundus), resulting in an inability to make the ''''A-OK'''' sign.'),
    (v_topic_id, 'A 2-year-old child refuses to bear weight on the right leg. The hip is held in flexion, abduction, and external rotation. Temperature is 39.5°C. Laboratory evaluation shows a WBC count of 15,000/mm³ and an ESR of 50 mm/hr. According to the Kocher criteria, what is the probability that this child has septic arthritis rather than transient synovitis?', '["About 25%", "Exactly 0%", "> 90% (Very high probability)", "< 10% (Very low probability)", "About 50%"]'::jsonb, 2, 'The Kocher criteria differentiate septic arthritis from transient synovitis. The 4 criteria are: non-weight-bearing, fever > 38.5°C, ESR > 40 mm/hr, and WBC > 12,000/mm³. Having all 4 predictors yields a 99% probability of septic arthritis; 3 predictors yield a 93% probability. This child has 4 predictors.'),
    (v_topic_id, 'A 18-day-old infant is brought to the clinic for bilateral clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Cavus", "Adductus", "Supination", "Equinus", "Varus"]'::jsonb, 3, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 27-day-old infant is brought to the clinic for bilateral clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Adductus", "Varus", "Cavus", "Equinus", "Supination"]'::jsonb, 3, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 5-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the bilateral. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["Bone scan", "MRI of the hips", "AP radiograph of the pelvis", "CT scan of the pelvis", "Ultrasound of the hips"]'::jsonb, 4, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 6-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the left. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["Ultrasound of the hips", "CT scan of the pelvis", "MRI of the hips", "AP radiograph of the pelvis", "Bone scan"]'::jsonb, 0, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'Patient #78451: A 10-month-old infant is referred to orthopedics for asymmetric gluteal folds and a leg length discrepancy. Which imaging modality is considered the gold standard to evaluate for Developmental Dysplasia of the Hip (DDH) at this specific age?', '["Ultrasound of the hips", "MRI of the pelvis", "AP radiograph of the pelvis", "CT scan", "Bone scan"]'::jsonb, 2, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 16-year-old female diver complains of insidious onset, mechanical low back pain that is exacerbated by extension activities (e.g., back walkovers). Neurologic exam is normal. Oblique radiographs of the lumbar spine demonstrate a ''collar'' on the ''Scotty dog''. What is the specific anatomic defect in this condition?', '["Fracture of the transverse process", "Defect in the pars interarticularis", "Congenital failure of segmentation of the lumbar vertebrae", "Herniation of the nucleus pulposus", "Defect in the vertebral body endplate (Schmorl node)"]'::jsonb, 1, 'Spondylolysis is a stress fracture or defect of the pars interarticularis. It is highly prevalent in adolescent athletes participating in sports involving repetitive lumbar hyperextension. On oblique radiographs, a radiolucent gap in the pars resembles a collar on the neck of the ''''Scotty dog''''.'),
    (v_topic_id, 'A 3-year-old falls from a swing and sustains a significantly displaced extension-type supracondylar humerus fracture. Upon examination, the child is unable to make an ''OK'' sign (unable to flex the IP joint of the thumb and DIP joint of the index finger). Which nerve is most likely injured?', '["Radial nerve", "Ulnar nerve", "Musculocutaneous nerve", "Anterior interosseous nerve (AIN)", "Axillary nerve"]'::jsonb, 3, 'The anterior interosseous nerve (AIN), a branch of the median nerve, is the most commonly injured nerve in extension-type supracondylar humerus fractures. Injury manifests as an inability to flex the IP joint of the thumb (flexor pollicis longus) and the DIP of the index finger (flexor digitorum profundus), resulting in an inability to make the ''''A-OK'''' sign.'),
    (v_topic_id, 'A 13-year-old volleyball player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Activity modification, ice, NSAIDs, and reassurance", "Surgical excision of the ossicle", "Immobilization in a long leg cast for 6 weeks", "Intra-articular corticosteroid injection", "Strict non-weight bearing with crutches"]'::jsonb, 0, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'A 12-year-old obese male presents with left groin and knee pain. He walks with a limp. On examination, when his left hip is passively flexed, it obligatorily goes into external rotation. Radiographs show a posterior and inferior displacement of the proximal femoral epiphysis. What is the most appropriate management?', '["Pavlik harness", "Immediate non-weight bearing and in situ percutaneous pinning", "Physical therapy and weight loss", "Closed reduction and spica casting", "Open reduction and internal fixation"]'::jsonb, 1, 'Slipped Capital Femoral Epiphysis (SCFE) occurs typically in overweight adolescents. The hallmark physical exam finding is obligatory external rotation with hip flexion. Treatment is strictly in situ pinning (without attempts at forceful closed reduction, which increases the risk of avascular necrosis) to stabilize the physis.'),
    (v_topic_id, 'A 15-year-old obese male presents with left groin and knee pain. He walks with a limp. On examination, when his left hip is passively flexed, it obligatorily goes into external rotation. Radiographs show a posterior and inferior displacement of the proximal femoral epiphysis. What is the most appropriate management?', '["Physical therapy and weight loss", "Pavlik harness", "Immediate non-weight bearing and in situ percutaneous pinning", "Open reduction and internal fixation", "Closed reduction and spica casting"]'::jsonb, 2, 'Slipped Capital Femoral Epiphysis (SCFE) occurs typically in overweight adolescents. The hallmark physical exam finding is obligatory external rotation with hip flexion. Treatment is strictly in situ pinning (without attempts at forceful closed reduction, which increases the risk of avascular necrosis) to stabilize the physis.'),
